3. Структура сервиса (MusicBrainzService)


Вот как я рекомендую организовать сервис:


Dart


Копировать


// services/musicbrainz_service.dart
import 'package:musicbrainz_api/musicbrainz_api.dart';
import 'package:thefuzz/thefuzz.dart' as fuzz;

class MusicBrainzService {
  final MusicBrainzApi _api = MusicBrainzApi(
    userAgent: 'FlowGroove/1.0 (your-email@example.com)', // ОБЯЗАТЕЛЬНО!
  );

  // Основной метод, который будет вызываться из UI
  Future<CanonicalSong?> searchCanonicalSong({
    required String title,
    required String artist,
  }) async {
    try {
      // 1. Поиск по Work
      final works = await _api.searchWork(
        query: '"$title" AND artist:"$artist"',
        limit: 10,
      );

      if (works.isEmpty) {
        // Пробуем более мягкий поиск
        final looseWorks = await _api.searchWork(
          query: '$title $artist',
          limit: 5,
        );
        works.addAll(looseWorks);
      }

      // 2. Fuzzy matching + выбор лучшего результата
      if (works.isNotEmpty) {
        final bestMatch = _findBestMatch(works, title, artist);

        if (bestMatch != null && bestMatch.score > 75) {
          return await _convertToCanonicalSong(bestMatch.work);
        }
      }

      return null; // Не нашли надёжного совпадения
    } catch (e) {
      print('MusicBrainz error: $e');
      return null;
    }
  }

  BestMatch? _findBestMatch(List<dynamic> works, String title, String artist) {
    double bestScore = 0;
    dynamic bestWork;

    for (var item in works) {
      final workTitle = item.work.title ?? '';
      final workArtist = item.work.artistCredit?.name ?? '';

      final titleScore = fuzz.ratio(title.toLowerCase(), workTitle.toLowerCase());
      final artistScore = fuzz.ratio(artist.toLowerCase(), workArtist.toLowerCase());

      final totalScore = (titleScore * 0.6) + (artistScore * 0.4);

      if (totalScore > bestScore) {
        bestScore = totalScore;
        bestWork = item.work;
      }
    }

    if (bestScore > 0) {
      return BestMatch(work: bestWork, score: bestScore);
    }
    return null;
  }

  Future<CanonicalSong> _convertToCanonicalSong(Work work) async {
    return CanonicalSong(
      id: '', // будет присвоен в Firebase
      title: work.title ?? '',
      originalArtist: work.artistCredit?.name ?? 'Unknown',
      mbid: work.id,
      iswc: work.iswc,
      year: work.date != null ? int.tryParse(work.date!.substring(0, 4)) : null,
      tags: work.tags?.map((t) => t.name ?? '').toList() ?? [],
    );
  }
}


